application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');

:root { --ink: #192b3a; --muted: #71808d; --line: #dce5e8; --cream: #f7f8f4; --mint: #dff3e9; --green: #28765f; --coral: #e97862; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; color: var(--ink); background: #f4f7f5; font-family: 'DM Sans', sans-serif; }
body:before { content: ''; position: fixed; inset: 0; z-index: -1; background: radial-gradient(circle at 8% 10%, #e3f3eb 0, transparent 30%), radial-gradient(circle at 95% 90%, #fde8df 0, transparent 28%); }
.app-shell { max-width: 1160px; margin: auto; padding: 58px 28px 32px; }
.hero { display: flex; gap: 19px; align-items: center; margin-bottom: 45px; }
.brand-mark { width: 54px; height: 54px; display: grid; place-items: center; border-radius: 17px; color: white; background: var(--green); font-size: 28px; box-shadow: 0 8px 20px #28765f30; }
.eyebrow { margin: 0 0 7px; color: var(--green); font-size: 11px; font-weight: 700; letter-spacing: .15em; text-transform: uppercase; }
h1, h2, h3, p { margin-top: 0; } h1 { margin-bottom: 8px; font-family: 'Playfair Display', serif; font-size: clamp(33px, 5vw, 50px); line-height: 1.05; letter-spacing: -.03em; } h2 { margin: 0; font-family: 'Playfair Display', serif; font-size: 26px; } h3 { margin-bottom: 6px; }
.hero-copy { max-width: 490px; margin: 0; color: var(--muted); font-size: 15px; line-height: 1.6; }
.layout-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr); gap: 24px; align-items: start; }
.panel { padding: 31px; border: 1px solid #ffffff; border-radius: 22px; background: rgba(255,255,255,.82); box-shadow: 0 15px 45px #173c3210; backdrop-filter: blur(8px); }
.section-heading { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 28px; }.step-badge, .count-badge { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; color: var(--green); background: var(--mint); font-size: 12px; font-weight: 700; }.count-badge { width: 30px; height: 30px; }
.field-group { margin-bottom: 19px; }.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; } label { display: block; margin-bottom: 8px; color: #536572; font-size: 12px; font-weight: 700; }
input, select { width: 100%; height: 48px; padding: 0 14px; border: 1px solid var(--line); border-radius: 10px; outline: none; color: var(--ink); background: #fbfcfb; font: inherit; font-size: 14px; transition: .2s; } input:focus, select:focus { border-color: var(--green); box-shadow: 0 0 0 3px #28765f18; } input:user-invalid:not(:focus) { border-color: #e5a091; }
.primary-button { width: 100%; height: 50px; margin-top: 8px; border: 0; border-radius: 10px; color: white; background: var(--green); cursor: pointer; font: 700 14px 'DM Sans'; transition: .2s; }.primary-button:hover { background: #1d614e; transform: translateY(-1px); }.primary-button span { margin-left: 8px; font-size: 18px; }
.privacy-note { margin: 16px 0 0; color: #8a979d; text-align: center; font-size: 11px; }.privacy-note span { color: var(--green); font-size: 16px; vertical-align: -1px; }
.confirmation { margin: -8px 0 22px; padding: 12px 14px; border-radius: 9px; color: #22634f; background: #e8f7ef; font-size: 13px; font-weight: 600; }.confirmation[hidden] { display: none; }
.booking-list { display: flex; flex-direction: column; gap: 12px; min-height: 280px; }.empty-state { display: grid; place-items: center; align-content: center; min-height: 280px; color: var(--muted); text-align: center; }.empty-icon { display: grid; place-items: center; width: 55px; height: 55px; margin-bottom: 15px; border-radius: 16px; color: var(--green); background: var(--mint); font-size: 26px; }.empty-state h3 { color: var(--ink); font-family: 'Playfair Display', serif; font-size: 20px; }.empty-state p { margin: 0; font-size: 13px; }
.booking-card { position: relative; padding: 18px 48px 17px 18px; border: 1px solid var(--line); border-left: 4px solid var(--green); border-radius: 12px; background: #fff; }.booking-card.cancelled { border-left-color: #aab4b8; opacity: .65; }.booking-card.cancelled .booking-person, .booking-card.cancelled .booking-detail { text-decoration: line-through; }.booking-person { margin: 0 0 7px; font-size: 16px; font-weight: 700; }.booking-type { display: inline-block; margin-left: 8px; padding: 4px 8px; border-radius: 20px; color: var(--green); background: var(--mint); font-size: 10px; font-weight: 700; }.booking-detail { margin: 3px 0; color: var(--muted); font-size: 12px; }.cancel-button { position: absolute; top: 15px; right: 14px; border: 0; color: #b56c60; background: none; cursor: pointer; font: 600 11px 'DM Sans'; }.cancel-button:hover { color: #963f31; } footer { margin-top: 30px; color: #9aa7a8; text-align: center; font-size: 11px; } footer span { padding: 0 8px; color: var(--coral); }
@media (max-width: 760px) { .app-shell { padding: 35px 17px 25px; }.hero { margin-bottom: 30px; }.layout-grid { grid-template-columns: 1fr; }.panel { padding: 23px 20px; } }
@media (max-width: 400px) { .field-row { grid-template-columns: 1fr; gap: 0; } }

application.javascript:
const form = document.getElementById('booking-form');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const confirmation = document.getElementById('confirmation');
const count = document.getElementById('booking-count');
const dateInput = document.getElementById('booking-date');

const today = new Date();
const localToday = new Date(today.getTime() - today.getTimezoneOffset() * 60000).toISOString().split('T')[0];
dateInput.min = localToday;

function formatDate(value) {
  return new Date(value + 'T00:00:00').toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
}

function updateCount() {
  count.textContent = list.querySelectorAll('[data-status="active"]').length;
}

function addBooking(data) {
  emptyState.hidden = true;
  const card = document.createElement('article');
  card.className = 'booking-card';
  card.dataset.testid = 'booking';
  card.dataset.status = 'active';
  card.innerHTML = `<p class="booking-person" data-testid="booking-name-display"></p><span class="booking-type"></span><p class="booking-detail">▣ &nbsp; <span class="date-text"></span> &nbsp;•&nbsp; <span class="time-text"></span></p><p class="booking-detail">✉ &nbsp; <span class="email-text"></span></p><button type="button" class="cancel-button" data-testid="booking-cancel">Cancel</button>`;
  card.querySelector('[data-testid="booking-name-display"]').textContent = data.name;
  card.querySelector('.booking-type').textContent = data.type;
  card.querySelector('.date-text').textContent = formatDate(data.date);
  card.querySelector('.time-text').textContent = data.time;
  card.querySelector('.email-text').textContent = data.email;
  card.querySelector('[data-testid="booking-cancel"]').addEventListener('click', () => {
    card.dataset.status = 'cancelled';
    card.classList.add('cancelled');
    const button = card.querySelector('[data-testid="booking-cancel"]');
    button.textContent = 'Cancelled';
    button.disabled = true;
    updateCount();
  });
  list.prepend(card);
  updateCount();
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!form.checkValidity()) { form.reportValidity(); return; }
  const data = Object.fromEntries(new FormData(form));
  if (data.date < localToday) {
    dateInput.setCustomValidity('Please choose today or a future date.');
    dateInput.reportValidity();
    dateInput.setCustomValidity('');
    return;
  }
  addBooking(data);
  confirmation.hidden = false;
  confirmation.textContent = `Booking confirmed for ${data.name} on ${formatDate(data.date)}.`;
  form.reset();
  dateInput.min = localToday;
  window.setTimeout(() => { confirmation.hidden = true; }, 6000);
});

form.addEventListener('input', () => { if (dateInput.value) dateInput.setCustomValidity(''); });
